import{_ as r,o as e,c as o,ag as a}from"./chunks/framework.QfQ7DfGu.js";const g=JSON.parse('{"title":"LoongArch模拟器简介","description":"","frontmatter":{"title":"LoongArch模拟器简介","outline":"deep"},"headers":[],"relativePath":"docs-la/others-la64-insn.md","filePath":"docs-la/others-la64-insn.md"}'),d={name:"docs-la/others-la64-insn.md"};function n(l,t,h,i,c,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="loongarch模拟器" tabindex="-1">LoongArch模拟器 <a class="header-anchor" href="#loongarch模拟器" aria-label="Permalink to &quot;LoongArch模拟器&quot;">​</a></h1><h2 id="la-emu模拟器" tabindex="-1"><strong>LA_EMU模拟器</strong> <a class="header-anchor" href="#la-emu模拟器" aria-label="Permalink to &quot;**LA_EMU模拟器**&quot;">​</a></h2><p>LoongArch64模拟器，支持整型，浮点，向量指令集。能够启动Linux。</p><p>支持的指令集如下所示：</p><table tabindex="0"><thead><tr><th>支持的特性（Features）</th><th>目前状态（Status）</th></tr></thead><tbody><tr><td>Loongarch64 base</td><td>✓</td></tr><tr><td>Loongarch64 privilege</td><td>✓</td></tr><tr><td>FP</td><td>✓</td></tr><tr><td>LSX</td><td>✓</td></tr><tr><td>LASX</td><td>✓</td></tr><tr><td>Timer</td><td>✓</td></tr><tr><td>Serial Port</td><td>✓</td></tr><tr><td>Gdb Server</td><td>✓</td></tr><tr><td>Determined events</td><td>✓</td></tr><tr><td>All SPEC CPU</td><td>✓</td></tr><tr><td>Dynamic ELF</td><td>✗</td></tr><tr><td>Multithread</td><td>✗</td></tr><tr><td>Signal</td><td>✗</td></tr><tr><td>Block Device</td><td>✗</td></tr></tbody></table><p>指令的实现基本都在这里：<a href="https://github.com/LoongsonLab/LA_EMU/blob/master/loongarch64/interpreter.c" target="_blank" rel="noreferrer">interpreter.c</a></p><p><a href="https://github.com/LoongsonLab/LA_EMU" target="_blank" rel="noreferrer">仓库地址</a></p><p>安装、使用与调试方法请查看文档[龙架构开发平台]中[模拟器]部分，或查看[LoongArch架构与OS交互]文档。</p><h2 id="loongarch-qemu" tabindex="-1">LoongArch-QEMU <a class="header-anchor" href="#loongarch-qemu" aria-label="Permalink to &quot;LoongArch-QEMU&quot;">​</a></h2><p>LoongArch-QEMU 是 QEMU 开源模拟器对龙芯自主指令集架构 LoongArch 的完整支持实现，为开发者提供了一个无需物理龙芯硬件即可体验和开发 LoongArch 生态的强大工具。</p><p>LoongArch-QEMU 支持User mode和System mode，支持启动 LoongArch 版 Linux 发行版（如 ArchLinux、UOS、Loongnix 等），模拟包括CPU、内存、存储、网络在内的全套硬件环境。</p><p><a href="https://github.com/qemu/qemu.git" target="_blank" rel="noreferrer">仓库地址</a></p><p>安装、使用与调试方法请查看文档[龙架构开发平台]中[模拟器]部分，或查看[LoongArch架构与OS交互]文档。</p><h2 id="loongarch32r-nemu" tabindex="-1">LoongArch32R-NEMU <a class="header-anchor" href="#loongarch32r-nemu" aria-label="Permalink to &quot;LoongArch32R-NEMU&quot;">​</a></h2><p>基于NEMU实现的LoongArch32-Reduced模拟器</p><p>本项目基于南京大学的 NEMU 项目，向其中移植了龙芯架构32位精简版的支持，即 LoongArch32-Reduced(以下简称为 LA32R)。</p><p>为了向 LA32R 的开发者、学习者、爱好者以及“龙芯杯”大赛提供一个类似于一生一芯项目中的 difftest 环境，基于 NEMU 项目，移植了LA32R指令集。</p><p>该模拟器是一个轻量级的指令集模拟器，运行效果相当于一个单周期CPU。</p><h2 id="实现情况" tabindex="-1">实现情况 <a class="header-anchor" href="#实现情况" aria-label="Permalink to &quot;实现情况&quot;">​</a></h2><p>本项目按照《龙芯架构32位精简版参考手册》实现，目前已经实现了：</p><ul><li>除浮点指令之外的全部指令</li><li>除时钟中断、硬件中断、浮点例外之外的全部中断例外支持</li><li>全部的 CSR 寄存器</li><li>项数可配置的 TLB MMU</li><li>向 difftest 框架提供的各 API</li></ul><p>目前尚未实现、无法实现以及不打算实现的内容：</p><ul><li>Cache：不打算实现</li><li>计时器和定时器：NEMU 无法模拟时钟周期，故无法实现</li><li>各种外设（包括串口）：尚未实现。本项目的最终目的是为了实现 difftest ，故外设支持的优先级靠后</li><li>配套的 AM （裸机运行时环境）：尚未实现。理由同上</li></ul><p><a href="https://gitee.com/loongsonlab/la32r-nemu" target="_blank" rel="noreferrer">仓库地址</a></p><p>安装、使用与调试方法请查看文档[龙架构开发平台]中[模拟器]部分。</p><h2 id="la32r-qemu" tabindex="-1">LA32R-QEMU <a class="header-anchor" href="#la32r-qemu" aria-label="Permalink to &quot;LA32R-QEMU&quot;">​</a></h2><p>基于开源LoongArch-QEMU构建的支持LoongArch32精简指令集的QEMU。</p><p>通过qemu（Quick Emulator），可以在宿主机上模拟运行编写的LA32R汇编程序。另外，QEMU的两种运行模式：User mode 和 System mode，LA32R-QEMU均可运行。</p><p><a href="https://gitee.com/loongson-edu/la32r-QEMU" target="_blank" rel="noreferrer">仓库地址</a></p><p>安装、使用与调试方法请查看文档[龙架构开发平台]中[模拟器]部分。</p>',30)])])}const u=r(d,[["render",n]]);export{g as __pageData,u as default};
